#!/usr/bin/env python3
"""`todo` CLI: a small personal task manager backed by a JSON file.

See SPEC.md for the full specification.
"""

import json
import os
import sys
from pathlib import Path


def storage_path():
    return Path(os.path.expanduser("~")) / ".todo" / "tasks.json"


def load_tasks():
    path = storage_path()
    if not path.exists():
        return []
    with open(path, "r") as f:
        data = json.load(f)
    return data.get("tasks", [])


def save_tasks(tasks):
    path = storage_path()
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "w") as f:
        json.dump({"tasks": tasks}, f)


def cmd_add(args):
    text = args[0] if args else ""
    if text == "":
        print("Error: task text must not be empty", file=sys.stderr)
        return 1

    tasks = load_tasks()
    existing_ids = [t["id"] for t in tasks]
    new_id = max(existing_ids) + 1 if existing_ids else 1
    tasks.append({"id": new_id, "text": text, "done": False})
    save_tasks(tasks)
    print(f"Added task {new_id}: {text}")
    return 0


def cmd_list(args):
    tasks = load_tasks()
    if not tasks:
        print("No tasks found.")
        return 0

    for task in sorted(tasks, key=lambda t: t["id"]):
        mark = "x" if task["done"] else " "
        print(f"[{mark}] {task['id']}: {task['text']}")
    return 0


def cmd_done(args):
    if not args:
        print("Error: invalid task id ''", file=sys.stderr)
        return 1

    raw_id = args[0]
    try:
        task_id = int(raw_id)
    except ValueError:
        print(f"Error: invalid task id '{raw_id}'", file=sys.stderr)
        return 1

    tasks = load_tasks()
    for task in tasks:
        if task["id"] == task_id:
            task["done"] = True
            save_tasks(tasks)
            print(f"Completed task {task_id}: {task['text']}")
            return 0

    print(f"Error: task {task_id} not found", file=sys.stderr)
    return 1


def main():
    argv = sys.argv[1:]
    if not argv:
        print("Error: no command given", file=sys.stderr)
        return 1

    command, rest = argv[0], argv[1:]
    if command == "add":
        return cmd_add(rest)
    elif command == "list":
        return cmd_list(rest)
    elif command == "done":
        return cmd_done(rest)
    else:
        print(f"Error: unknown command '{command}'", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())

